CREATE POLICY "site_photos_read" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'site-photos');
CREATE POLICY "site_photos_upload" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'site-photos' AND (public.can('site_ops','edit') OR public.is_admin()));
CREATE POLICY "site_photos_update" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'site-photos' AND (public.can('site_ops','edit') OR public.is_admin()));
CREATE POLICY "site_photos_delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'site-photos' AND (public.can('site_ops','edit') OR public.is_admin()));